// src/components/User/HomePage.js
import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import './HomePage.css';

// Define the categories and corresponding SVG paths/structure
const CATEGORY_ICONS = {
  Pizza: (
    <svg viewBox="0 0 24 24" width="30" height="30" fill="none" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round">
      <circle cx="12" cy="12" r="10" />
      <path d="M12 2a10 10 0 0 0-7 3m14 0a10 10 0 0 0-7-3" />
      <path d="M12 2a10 10 0 0 1 7 3" />
      <path d="M12 2a10 10 0 0 1-7 3" />
      <circle cx="9" cy="9" r="1" fill="currentColor" />
      <circle cx="15" cy="15" r="1" fill="currentColor" />
      <circle cx="12" cy="15" r="1" fill="currentColor" />
      <circle cx="15" cy="9" r="1" fill="currentColor" />
    </svg>
  ),
  Burger: (
    <svg viewBox="0 0 24 24" width="30" height="30" fill="none" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round">
      <path d="M11 17H4a2 2 0 0 1-2-2V9a2 2 0 0 1 2-2h7" />
      <path d="M13 17h7a2 2 0 0 0 2-2V9a2 2 0 0 0-2-2h-7" />
      <path d="M2 9h20" />
      <path d="M2 15h20" />
      <circle cx="12" cy="12" r="2" />
    </svg>
  ),
  Drink: (
    <svg viewBox="0 0 24 24" width="30" height="30" fill="none" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round">
      <path d="M6 8h12v12a2 2 0 0 1-2 2H8a2 2 0 0 1-2-2V8z" />
      <line x1="12" y1="2" x2="12" y2="8" />
      <line x1="8" y1="2" x2="16" y2="2" />
    </svg>
  ),
  'French fries': (
    <svg viewBox="0 0 24 24" width="30" height="30" fill="none" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round">
      <path d="M4 10h16" />
      <path d="M10 20v-5" />
      <path d="M14 20v-5" />
      <path d="M6 20v-5" />
      <path d="M18 20v-5" />
      <rect x="3" y="4" width="18" height="16" rx="2" />
      <line x1="9" y1="15" x2="9" y2="4" />
      <line x1="15" y1="15" x2="15" y2="4" />
    </svg>
  ),
  Veggies: (
