const CATEGORIES = [
  'Appetizers',
  'Soups',
  'Sandwiches & Wraps',
  'Pizza', 
  'Burger', 
  'Drink', 
  'French fries', 
  'Veggies',
  'Desserts',
];

export default function HomePage({ menu = [], cart = [], addToCart }) {
  const [selectedCategory, setSelectedCategory] = useState('Appetizers'); 
  const [searchTerm, setSearchTerm] = useState('');
  const navigate = useNavigate();

  // Filter logic
  const filteredMenu = menu.filter(item => {
    const matchesCategory = item.category === selectedCategory;
    const matchesSearch = item.name.toLowerCase().includes(searchTerm.toLowerCase());
    return matchesCategory && matchesSearch;
  });

  const cartItemCount = cart.reduce((acc, item) => acc + item.quantity, 0);

  return (
    <div className="mobile-container">
      <header className="home-header">
        <h1>Good evening</h1>
        <p>Place you order here</p>
      </header>

      <div className="search-bar">
        <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={1.5} stroke="currentColor" className="search-icon">
          <path strokeLinecap="round" strokeLinejoin="round" d="M21 21l-5.197-5.197m0 0A7.5 7.5 0 105.196 5.196a7.5 7.5 0 0010.607 10.607z" />
        </svg>
        <input 
          type="text" 
          placeholder="Search"
          value={searchTerm}
          onChange={(e) => setSearchTerm(e.target.value)}
        />
      </div>

      <nav className="category-nav">
        {CATEGORIES.map(category => (
          <button 
            key={category}
            className={`category-btn with-icon ${selectedCategory === category ? 'active' : ''}`}
            onClick={() => setSelectedCategory(category)}
          >
            {/* Display the icon above the text */}
            <div className="category-icon-wrapper">
              {CATEGORY_ICONS[category] || <span>🍽️</span>} 
            </div>
            {category}
          </button>
        ))}
      </nav>

      <section className="menu-list">
        <h2>{selectedCategory}</h2>
        {filteredMenu.map(item => (
          <div key={item.id} className="menu-item">
            <img src={item.image} alt={item.name} className="item-image" />
            <div className="item-details">
              <h3>{item.name}</h3>
              <p>₹{item.price}</p>
            </div>
            <button className="add-btn" onClick={() => addToCart(item)}>+</button>
          </div>
        ))}
      </section>

      {cartItemCount > 0 && (
        <div className="next-button-container">
          <button className="next-btn" onClick={() => navigate('/checkout')}>
            <span>{cartItemCount} Item{cartItemCount > 1 ? 's' : ''}</span>
            <span>Next</span>
          </button>
        </div>
      )}
    </div>
  );
}
